description:
Write the helpers for putting shapes where you mean them:

```cpp
struct Vector2 { float x, y; };
struct Rectangle { float x, y, width, height; };
struct Color { unsigned char r, g, b, a; };

Rectangle centred(int screenW, int screenH, float w, float h);   // a w x h rectangle in the middle of the screen
Rectangle circleBounds(Vector2 centre, float radius);            // the square around a circle
Vector2 rectCentre(Rectangle r);
Color colorLerp(Color a, Color b, float t);                      // each channel a + (b - a) * t, rounded; t clamped to 0..1
```

starter.solution.cpp:
struct Vector2 { float x, y; };
struct Rectangle { float x, y, width, height; };
struct Color { unsigned char r, g, b, a; };

Rectangle centred(int screenW, int screenH, float w, float h) { return { 0, 0, 0, 0 }; }
Rectangle circleBounds(Vector2 centre, float radius) { return { 0, 0, 0, 0 }; }
Vector2 rectCentre(Rectangle r) { return { 0, 0 }; }
Color colorLerp(Color a, Color b, float t) { return a; }

solution.solution.cpp:
#include <algorithm>
#include <cmath>

struct Vector2 { float x, y; };
struct Rectangle { float x, y, width, height; };
struct Color { unsigned char r, g, b, a; };

Rectangle centred(int screenW, int screenH, float w, float h)
{
    return { (screenW - w) / 2.0f, (screenH - h) / 2.0f, w, h };
}

Rectangle circleBounds(Vector2 centre, float radius)
{
    return { centre.x - radius, centre.y - radius, radius * 2, radius * 2 };
}

Vector2 rectCentre(Rectangle r)
{
    return { r.x + r.width / 2, r.y + r.height / 2 };
}

Color colorLerp(Color a, Color b, float t)
{
    t = std::clamp(t, 0.0f, 1.0f);
    auto mix = [t](unsigned char x, unsigned char y) { return static_cast<unsigned char>(std::lround(x + (y - x) * t)); };
    return { mix(a.r, b.r), mix(a.g, b.g), mix(a.b, b.b), mix(a.a, b.a) };
}

unitTests:
bool sameRect(Rectangle r, float x, float y, float w, float h) { return std::fabs(r.x - x) < 1e-4f && std::fabs(r.y - y) < 1e-4f && std::fabs(r.width - w) < 1e-4f && std::fabs(r.height - h) < 1e-4f; }
TEST("centred") { CHECK(sameRect(centred(800, 450, 200, 50), 300, 200, 200, 50)); CHECK(sameRect(centred(801, 450, 100, 451), 350.5f, -0.5f, 100, 451)); }
TEST("circle bounds") { CHECK(sameRect(circleBounds({ 100, 60 }, 10), 90, 50, 20, 20)); }
TEST("rect centre") { const Vector2 c = rectCentre({ 10, 20, 30, 40 }); CHECK_NEAR(c.x, 25.0, 1e-4); CHECK_NEAR(c.y, 40.0, 1e-4); }
TEST("colour lerp") {
    const Color red{ 230, 41, 55, 255 }, blue{ 0, 121, 241, 255 };
    const Color m = colorLerp(red, blue, 0.5f); CHECK_EQ(int(m.r), 115); CHECK_EQ(int(m.g), 81); CHECK_EQ(int(m.b), 148); CHECK_EQ(int(m.a), 255);
    CHECK_EQ(int(colorLerp(red, blue, 2.0f).b), 241); CHECK_EQ(int(colorLerp(red, blue, -1.0f).r), 230);
}

